    modal: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 },
    modalContent: { backgroundColor: 'white', padding: '24px', borderRadius: '12px', maxWidth: '500px', width: '90%' },
    modalInput: { width: '100%', padding: '10px', marginBottom: '10px', border: '1px solid #d1d5db', borderRadius: '6px' },
    modalTextarea: { width: '100%', padding: '10px', marginBottom: '10px', border: '1px solid #d1d5db', borderRadius: '6px', minHeight: '80px' },
    pendingItem: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px', borderBottom: '1px solid #e5e7eb', flexWrap: 'wrap', gap: '10px' },
    transactionItem: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px', borderBottom: '1px solid #e5e7eb', flexWrap: 'wrap', gap: '10px' },
    emptyState: { textAlign: 'center', padding: '40px', color: '#6b7280' }
  };

  if (loading) {
    return (
      <div style={styles.container}>
        <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ textAlign: 'center' }}>
            <div style={{ fontSize: '48px', marginBottom: '20px' }}>👑</div>
            <div style={{ fontSize: '18px', color: '#6b7280' }}>Loading admin dashboard...</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <ToastContainer position="top-right" />

      {/* Sidebar */}
      <div style={styles.sidebar}>
        <div style={styles.sidebarHeader}>
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <span style={styles.logoIcon}>👑</span>
            <span style={styles.logoText}>Car Care</span>
          </div>
          <button style={styles.collapseBtn} onClick={() => setSidebarCollapsed(!sidebarCollapsed)}>
            {sidebarCollapsed ? '→' : '←'}
          </button>
        </div>
        <div style={styles.sidebarMenu}>
          {menuItems.map(item => (
            <div
              key={item.id}
              style={{
                ...styles.menuItem,
                ...(activeTab === item.id ? styles.menuItemActive : {}),
                borderLeft: activeTab === item.id ? '3px solid ' + item.color : 'none'
              }}
              onClick={() => setActiveTab(item.id)}
            >
              <span style={styles.menuIcon}>{item.icon}</span>
              <span style={styles.menuLabel}>{item.label}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Main Content */}
      <div style={styles.mainContent}>
        {/* Top Header */}
        <div style={styles.topHeader}>
          <div style={styles.headerTitle}>
            {menuItems.find(m => m.id === activeTab)?.label || 'Dashboard'}
          </div>
          <div style={styles.headerRight}>
            <div style={styles.wsBadge}>
              <span style={{ width: '8px', height: '8px', backgroundColor: isConnected ? '#10b981' : '#ef4444', borderRadius: '50%', display: 'inline-block' }}></span>
              {isConnected ? 'Live' : 'Offline'}
            </div>
            <button style={styles.enableNotificationsBtn} onClick={requestNotificationPermission}>🔔 Enable Notifications</button>
            <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>
              🔔{unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}
            </div>
            <button style={styles.themeToggle} onClick={() => setDarkMode(!darkMode)}>
              {darkMode ? '☀️' : '🌙'}
            </button>
            <div style={styles.userInfo}>
              <div style={styles.avatar}>
                {user?.firstName?.charAt(0) || 'A'}
              </div>
              <div>
                <div style={styles.userName}>{user?.firstName} {user?.lastName}</div>
                <div style={{ fontSize: '11px', color: '#8b5cf6' }}>Administrator</div>
              </div>
              <button style={styles.logoutBtn} onClick={onLogout}>Logout</button>
            </div>
          </div>
        </div>

        {/* Notification Dropdown */}
        {showNotifications && (
          <div style={{
            position: 'absolute', top: '70px', right: '30px', width: '350px', backgroundColor: 'white',
            borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', zIndex: 1000, maxHeight: '400px', overflow: 'auto'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px', borderBottom: '1px solid #e5e7eb' }}>
              <h3 style={{ margin: 0 }}>Notifications</h3>
              <button onClick={() => { setNotifications([]); setUnreadCount(0); }} style={{ color: '#8b5cf6', background: 'none', border: 'none', cursor: 'pointer' }}>Clear all</button>
            </div>
            {notifications.length === 0 ? (
              <div style={{ padding: '30px', textAlign: 'center', color: '#6b7280' }}>No notifications</div>
            ) : (
              notifications.map((notif, idx) => (
                <div key={idx} style={{ display: 'flex', gap: '12px', padding: '12px 15px', borderBottom: '1px solid #e5e7eb' }}>
                  <span style={{ fontSize: '20px' }}>🔔</span>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>{notif.title || 'Update'}</div>
                    <div style={{ fontSize: '12px', color: '#6b7280' }}>{notif.message}</div>
                    <div style={{ fontSize: '10px', color: '#9ca3af', marginTop: '4px' }}>{new Date(notif.timestamp).toLocaleTimeString()}</div>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {/* Content Area */}
        <div style={styles.contentArea}>
          {/* Stats Cards */}
          <div style={styles.statsGrid}>
            <div style={styles.statCard}><div style={styles.statIcon}>💰</div><div style={styles.statInfo}><div style={styles.statValue}>${stats.payments?.totalRevenue?.toLocaleString() || 0}</div><div style={styles.statLabel}>Total Revenue</div></div></div>
            <div style={styles.statCard}><div style={styles.statIcon}>🏦</div><div style={styles.statInfo}><div style={styles.statValue}>${stats.payments?.totalCommission?.toLocaleString() || 0}</div><div style={styles.statLabel}>Platform Fee</div></div></div>
            <div style={styles.statCard}><div style={styles.statIcon}>👥</div><div style={styles.statInfo}><div style={styles.statValue}>{stats.users?.total || 0}</div><div style={styles.statLabel}>Total Users</div></div></div>
            <div style={styles.statCard}><div style={styles.statIcon}>📅</div><div style={styles.statInfo}><div style={styles.statValue}>{stats.bookings?.total || 0}</div><div style={styles.statLabel}>Bookings</div></div></div>
            <div style={styles.statCard}><div style={styles.statIcon}>🔧</div><div style={styles.statInfo}><div style={styles.statValue}>{stats.users?.providers || 0}</div><div style={styles.statLabel}>Providers</div></div></div>
            <div style={styles.statCard}><div style={styles.statIcon}>🚗</div><div style={styles.statInfo}><div style={styles.statValue}>{stats.users?.drivers || 0}</div><div style={styles.statLabel}>Drivers</div></div></div>
          </div>

          {/* Online Users & Activity - Only on Dashboard */}
          {(activeTab === 'dashboard') && (
            <>
              <div style={styles.onlineCard}>
                <div style={styles.cardTitle}>
                  <span>🟢 REAL-TIME ONLINE USERS</span>
                  <span style={styles.onlineDot}></span>
                  <span style={{ fontSize: '11px', fontWeight: 'normal', color: '#6b7280' }}>Live updates</span>
                </div>
                <div>
                  <div><strong>🚗 Drivers Online:</strong> {onlineUsers.drivers.length}</div>
                  <div style={styles.driverList}>
                    {onlineUsers.drivers.length === 0 ? (
                      <span style={{ fontSize: '12px', color: '#6b7280' }}>No drivers online</span>
                    ) : (
                      onlineUsers.drivers.map(driver => (
                        <div key={driver.id} style={styles.driverItem}>
                          <span style={{ width: '8px', height: '8px', backgroundColor: '#10b981', borderRadius: '50%', display: 'inline-block' }}></span>
                          {driver.name || driver.driverName || 'Driver'}
                          <span style={{ fontSize: '10px', color: '#6b7280' }}>• Active</span>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>

              <div style={styles.activityCard}>
                <div style={styles.cardTitle}>
                  <span>📡 LIVE ACTIVITY FEED</span>
                  <span style={{ fontSize: '11px', fontWeight: 'normal', color: '#6b7280' }}>Real-time platform events</span>
                </div>
                {liveActivity.length === 0 ? (
                  <div style={{ textAlign: 'center', color: '#6b7280', padding: '20px' }}>Waiting for activity...</div>
                ) : (
                  liveActivity.map(activity => (
                    <div key={activity.id} style={styles.activityItem}>
                      <span>{activity.type === 'driver_status' ? '🚗' : activity.type === 'booking_status' ? '📅' : '🔔'}</span>
                      <span>{activity.message}</span>
                      <span style={{ fontSize: '10px', color: '#9ca3af' }}>{new Date(activity.timestamp).toLocaleTimeString()}</span>
                    </div>
                  ))
                )}
              </div>
            </>
          )}

          {/* Tabs for different sections - Continue with existing tabs... */}
          {/* Keep all the existing tab content from the previous AdminDashboard */}
          {/* For brevity, the tab content structure remains the same as before */}

        </div>
      </div>

      {/* Refund Review Modal */}
      {selectedRefund && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2 style={{ marginBottom: '20px' }}>Review Refund Request</h2>
            <div style={{ marginBottom: '20px' }}>
              <p><strong>Customer:</strong> {selectedRefund.customerId?.firstName} {selectedRefund.customerId?.lastName}</p>
              <p><strong>Email:</strong> {selectedRefund.customerId?.email}</p>
              <p><strong>Service:</strong> {selectedRefund.bookingId?.serviceName}</p>
              <p><strong>Amount:</strong> ${selectedRefund.amount}</p>
              <p><strong>Reason:</strong> {selectedRefund.reason}</p>
            </div>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '500' }}>Admin Notes (Optional)</label>
            <textarea style={styles.modalTextarea} placeholder="Add internal notes..." value={adminNotes} onChange={(e) => setAdminNotes(e.target.value)} rows="3" />
            <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
              <button style={{ backgroundColor: '#10b981', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => approveRefund(selectedRefund._id)}>✅ Approve Refund</button>
              <button style={{ backgroundColor: '#ef4444', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => { setRejectionReason(''); }}>❌ Reject</button>
              <button style={{ backgroundColor: '#6b7280', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => { setSelectedRefund(null); setAdminNotes(''); setRejectionReason(''); }}>Cancel</button>
            </div>
            {rejectionReason && (
              <div style={{ marginTop: '20px', paddingTop: '20px', borderTop: '1px solid #e5e7eb' }}>
                <label style={{ display: 'block', marginBottom: '8px', fontWeight: '500' }}>Rejection Reason *</label>
                <textarea style={styles.modalTextarea} placeholder="Why is this refund being rejected?" value={rejectionReason} onChange={(e) => setRejectionReason(e.target.value)} rows="2" />
                <button style={{ marginTop: '10px', backgroundColor: '#ef4444', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => rejectRefund(selectedRefund._id)}>Confirm Rejection</button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminDashboard;
